CREATE OR REPLACE FUNCTION insert_into_user_view()
RETURNS TRIGGER AS $$
DECLARE
    v_user_id UUID;
BEGIN
    INSERT INTO users (email, name) VALUES (NEW.email, NEW.name) RETURNING id INTO v_user_id;
    INSERT INTO profiles (user_id, bio) VALUES (v_user_id, NEW.bio);
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER trg_user_view_insert
INSTEAD OF INSERT ON user_directory_view
FOR EACH ROW EXECUTE FUNCTION insert_into_user_view();

CREATE OR REPLACE FUNCTION customers_with_address_ins()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
    IF TG_OP = 'INSERT' THEN
        INSERT INTO customers (id, name)
        VALUES (NEW.id, NEW.name);

        INSERT INTO addresses (customer_id, city)
        VALUES (NEW.id, NEW.city);

        RETURN NEW;
    END IF;

    RETURN NULL;
END $$;

CREATE TRIGGER trg_customers_with_address
INSTEAD OF INSERT ON customers_with_address
FOR EACH ROW
EXECUTE FUNCTION customers_with_address_ins();

